def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    last_me, last_opp = history[-1]

    my_def = 0
    opp_def = 0
    for a, b in history:
        if a == 'D':
            my_def += 1
        if b == 'D':
            opp_def += 1

    opp_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            opp_streak += 1
        else:
            break

    recent_opp_def = 0
    start = n - 6
    if start < 0:
        start = 0
    for i in range(start, n):
        if history[i][1] == 'D':
            recent_opp_def += 1

    recent_my_def = 0
    start = n - 4
    if start < 0:
        start = 0
    for i in range(start, n):
        if history[i][0] == 'D':
            recent_my_def += 1

    hostile = False
    if n >= 3 and opp_def >= 3 and opp_def * 2 >= n:
        hostile = True
    if opp_streak >= 4 or recent_opp_def >= 5:
        hostile = True

    if n >= 98:
        return 'D'

    if last_opp == 'D':
        if hostile:
            return 'D'

        if last_me == 'C':
            if opp_streak >= 2 or recent_opp_def >= 3:
                return 'D'
            if recent_my_def > 0 and opp_def <= my_def + 2 and recent_opp_def <= 2:
                return 'C'
            return 'D'
        else:
            if opp_streak >= 3 or recent_opp_def >= 4:
                return 'D'
            if opp_def > my_def + 1 and n >= 10:
                return 'D'
            return 'C'

    if last_me == 'D':
        return 'C'

    if n < 10:
        return 'C'

    if opp_def == 0:
        if (
            n >= 12
            and history[-2][0] == 'D'
            and history[-2][1] == 'C'
            and history[-1][0] == 'C'
            and history[-1][1] == 'C'
        ):
            return 'D'
        if rng.random() < 0.2:
            return 'D'

    return 'C'
